sp_widget.client_script:
function($scope, $rootScope, spUtil, $timeout) {
  $scope.anoSelecionado = "";
  $scope.latestYear = null;
  $scope.dadosVisiveis = null; // controla se dados existem
  $scope.isFading = false;
  var currentAngle = 0;
  var animationFrameId = null;

  function loadChartJs() {
    return new Promise(function(resolve) {
      if (window.Chart) {
        resolve();
        return;
      }
      var script = document.createElement('script');
      script.src = 'https://cdn.jsdelivr.net/npm/chart.js';
      script.onload = resolve;
      document.head.appendChild(script);
    });
  }

  function mapValueToAngle(realValue) {
    var relativeAngleDeg = 0;
    if (realValue <= 57) {
      relativeAngleDeg = (realValue / 57) * 60;
    } else if (realValue <= 60) {
      relativeAngleDeg = 60 + ((realValue - 57) / 3) * 60;
    } else {
      relativeAngleDeg = 120 + ((realValue - 60) / 40) * 60;
    }
    return (relativeAngleDeg * Math.PI) / 180;
  }

  function syncPointerCanvasSize() {
    var chartCanvas = document.getElementById('gaugeChart');
    var pointerCanvas = document.getElementById('gaugePointer');
    if (!chartCanvas || !pointerCanvas) return;
    pointerCanvas.width = chartCanvas.offsetWidth;
    pointerCanvas.height = chartCanvas.offsetHeight;
  }

  function drawPointerAtAngle(angle) {
    var canvas = document.getElementById('gaugePointer');
    var ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    var width = canvas.width;
    var height = canvas.height;
    var cx = width / 2;
    var cy = height;
    var length = height * 0.75;

    var tipX = cx + length * Math.cos(Math.PI - angle);
    var tipY = cy - length * Math.sin(Math.PI - angle);

    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(tipX, tipY);
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 3;
    ctx.stroke();

    var arrowHeadLength = height * 0.08;
    var arrowHeadWidth = height * 0.05;

    var ux = Math.cos(Math.PI - angle);
    var uy = -Math.sin(Math.PI - angle);

    var baseX = tipX - arrowHeadLength * ux;
    var baseY = tipY - arrowHeadLength * uy;

    var leftX = baseX + (arrowHeadWidth / 2) * uy;
    var leftY = baseY + (arrowHeadWidth / 2) * -ux;

    var rightX = baseX - (arrowHeadWidth / 2) * uy;
    var rightY = baseY - (arrowHeadWidth / 2) * -ux;

    ctx.beginPath();
    ctx.moveTo(tipX, tipY);
    ctx.lineTo(leftX, leftY);
    ctx.lineTo(rightX, rightY);
    ctx.closePath();
    ctx.fillStyle = '#333';
    ctx.fill();

    ctx.beginPath();
    ctx.arc(cx, cy, 5, 0, 2 * Math.PI);
    ctx.fill();
  }

  function animatePointer(toAngle) {
    if (animationFrameId) cancelAnimationFrame(animationFrameId);

    var duration = 600;
    var startAngle = currentAngle;
    var delta = toAngle - startAngle;
    var startTime = performance.now();

    function step(now) {
      var elapsed = now - startTime;
      var progress = Math.min(elapsed / duration, 1);
      currentAngle = startAngle + delta * (1 - Math.pow(1 - progress, 3));
      drawPointerAtAngle(currentAngle);
      if (progress < 1) {
        animationFrameId = requestAnimationFrame(step);
      }
    }

    requestAnimationFrame(step);
  }

  function renderGauge(comprometimento) {
    var ctx = document.getElementById('gaugeChart').getContext('2d');

    if (window.myGaugeChart) {
      window.myGaugeChart.destroy();
    }

    window.myGaugeChart = new Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: ['Limite de alerta', 'Limite prudencial', 'Limite máximo'],
        datasets: [{
          data: [33.33, 33.33, 33.34],
          backgroundColor: ['#8BC34A', '#FFEB3B', '#F44336'],
          borderWidth: 0,
          circumference: 180,
          rotation: 270,
          cutout: '70%'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: false },
          tooltip: {
            enabled: true,
            callbacks: {
              label: function(context) {
                return context.chart.data.labels[context.dataIndex] || '';
              }
            }
          }
        }
      }
    });

    $timeout(function() {
      syncPointerCanvasSize();
      var targetAngle = mapValueToAngle(comprometimento);
      animatePointer(targetAngle);
    }, 200);
  }

  function atualizarDados(ano) {
    $scope.isFading = true;

    $timeout(function() {
      if (!ano) {
        $scope.latestYear = null;
        $scope.dadosVisiveis = null;
        if (window.myGaugeChart) {
          window.myGaugeChart.destroy();
          window.myGaugeChart = null;
        }
        var ctxPointer = document.getElementById('gaugePointer');
        if (ctxPointer) {
          var ctx = ctxPointer.getContext('2d');
          ctx.clearRect(0, 0, ctxPointer.width, ctxPointer.height);
        }
      } else {
        spUtil.get('widget_limite_com_despesas_semidonut', { filtro_ano: ano }).then(function(response) {
          if (response.data && response.data.dados && response.data.dados.length > 0) {
            $scope.dadosVisiveis = response.data.dados[0];
            $scope.latestYear = ano;
            renderGauge($scope.dadosVisiveis.comprometimento);
          } else {
            $scope.dadosVisiveis = null;
            $scope.latestYear = null;
            if (window.myGaugeChart) {
              window.myGaugeChart.destroy();
              window.myGaugeChart = null;
            }
            var ctxPointer = document.getElementById('gaugePointer');
            if (ctxPointer) {
              var ctx = ctxPointer.getContext('2d');
              ctx.clearRect(0, 0, ctxPointer.width, ctxPointer.height);
            }
          }
        });
      }

      $scope.isFading = false;
    }, 500);
  }

  $scope.anoChanged = function() {
    if ($scope.anoSelecionado && ($scope.anoSelecionado < 2000 || $scope.anoSelecionado > new Date().getFullYear())) {
      console.warn("Ano fora do intervalo permitido.");
      return;
    }
    $rootScope.$broadcast('anoSelecionado', $scope.anoSelecionado);
  };

  loadChartJs().then(function() {
    $rootScope.$on('anoSelecionado', function(evt, ano) {
      $scope.anoSelecionado = ano;
      atualizarDados(ano);
    });

    window.addEventListener('resize', function() {
      if ($scope.dadosVisiveis && $scope.dadosVisiveis.comprometimento != null) {
        syncPointerCanvasSize();
        var angle = mapValueToAngle($scope.dadosVisiveis.comprometimento);
        drawPointerAtAngle(angle);
      }
    });
  });
}

sp_widget.css:
.report-widget {
  border-radius: 12px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.08);
  background-color: #fff;
  margin-top: 24px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-family: 'Roboto Flex', sans-serif;

  opacity: 1;
  visibility: visible;
  transform: translateY(0);
  transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out, visibility 0.5s ease-in-out;
}

.report-widget.panel.fade-out {
  opacity: 0;
  visibility: hidden;
  transform: translateY(20px);

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  .report-widget {
    margin-top: 1rem;
  }
  .panel-title {
    font-size: 1.5rem;
  }
  .panel-body {
    padding: 8px;
  }
  .chart-container {
    height: 200px; /* Ajustar altura do gráfico */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  .report-widget {
    margin-top: 1.5rem;
  }
  .panel-title {
    font-size: 1.1rem;
  }
  .chart-container {
    height: 220px; /* Ajustar altura do gráfico */
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  .report-widget {
    margin-top: 24px;
  }
  .panel-title {
    font-size: 1.6rem;
  }
  .chart-container {
    height: 250px;
  }
}

/* Ajustes específicos para dispositivos muito largos como Nest Hub Max ou telas 4K */
@media (min-width: 1280px) {
    .panel-heading {
       padding: 14px 18px;
       font-size: 1.5rem;
    }
    .panel-body {
        padding: 20px;
    }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    .report-widget {
        margin-top: 1.2rem;
    }
    .panel-title {
        font-size: 1rem;
    }
    .chart-container {
        height: 210px;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    .panel-title {
        font-size: 0.9rem;
    }
    .panel-body {
        padding: 6px;
    }
    .chart-container {
        height: 180px;
    }
}

}

.panel-heading {
